      await post(`/projects/1/tasks/${id}/due-date`, { dueDate: '2025-04-01' });
    }
    const state = { filter: 'Open', priorityFilter: 'High', rangeFrom: '2025-04-01', rangeThrough: '2025-04-01', taskSearch: 'read' };
